1: using System.Collections;
2: using UnityEngine;
3: using UnityEngine.UI;
4: 
5: /// <summary>
6: /// Controls an in-game speech bubble floating directly over/next to a character.
7: /// Supports smooth pop-in animation, customizable tail, auto-dismiss, and billboard facing camera.
8: /// </summary>
9: public class CharacterSpeechBubble : MonoBehaviour
10: {
11:     [Header("Target & Position")]
12:     [Tooltip("Target transform to follow in 3D world (e.g. character head)")]
13:     public Transform followTarget;
14:     [Tooltip("World offset from target position")]
15:     public Vector3 worldOffset = new Vector3(0f, 2.2f, 0f);
16:     [Tooltip("Whether to billboard/face main camera in World Space")]
17:     public bool faceCamera = true;
18: 
19:     [Header("UI References")]
20:     public CanvasGroup canvasGroup;
21:     public RectTransform bubbleContainer;
22:     public Text dialogueText;
23:     public Text speakerNameText;
24:     public Image bubbleBackground;
25:     public Image bubbleTail;
26:     public Image iconImage;
27: 
28:     [Header("Behavior")]
29:     [Tooltip("Auto hide after seconds (0 = do not auto-hide)")]
30:     public float autoHideDuration = 5f;
31:     [Tooltip("Typewriter effect speed (chars per second, 0 = instant)")]
32:     public float typewriterSpeed = 35f;
33:     [Tooltip("Scale punch animation duration")]
34:     public float popDuration = 0.25f;
35: 
36:     [Header("Current State")]
37:     public bool isVisible = false;
38: 
39:     private Coroutine _showRoutine;
40:     private Coroutine _typewriterRoutine;
41:     private Coroutine _autoHideRoutine;
42:     private Camera _mainCamera;
43: 
44:     void Awake()
45:     {
46:         _mainCamera = Camera.main;
47:         if (canvasGroup == null) canvasGroup = GetComponent<CanvasGroup>();
48:         if (bubbleContainer == null) bubbleContainer = transform as RectTransform;
49: 
50:         // Start hidden by default
51:         if (canvasGroup != null)
52:         {
53:             canvasGroup.alpha = 0f;
54:             canvasGroup.blocksRaycasts = false;
55:         }
56:         if (bubbleContainer != null)
57:         {
58:             bubbleContainer.localScale = Vector3.zero;
59:         }
60:         isVisible = false;
61:     }
62: 
63:     void LateUpdate()
64:     {
65:         if (followTarget != null)
66:         {
67:             transform.position = followTarget.position + worldOffset;
68:         }
69: 
70:         if (faceCamera)
71:         {
72:             if (_mainCamera == null) _mainCamera = Camera.main;
73:             if (_mainCamera != null)
74:             {
75:                 // Face camera rotation
76:                 transform.rotation = _mainCamera.transform.rotation;
77:             }
78:         }
79:     }
80: 
81:     public void SetSpeakerName(string speakerName)
82:     {
83:         if (speakerNameText != null)
84:         {
85:             speakerNameText.text = speakerName ?? string.Empty;
86:             speakerNameText.gameObject.SetActive(!string.IsNullOrEmpty(speakerName));
87:         }
88:     }
89: 
90:     public void ShowText(string text, string speaker = null)
91:     {
92:         if (string.IsNullOrEmpty(text))
93:         {
94:             Hide();
95:             return;
96:         }
97: 
98:         if (speaker != null)
99:         {
100:             SetSpeakerName(speaker);
101:         }
102: 
103:         if (_showRoutine != null) StopCoroutine(_showRoutine);
104:         if (_typewriterRoutine != null) StopCoroutine(_typewriterRoutine);
105:         if (_autoHideRoutine != null) StopCoroutine(_autoHideRoutine);
106: 
107:         _showRoutine = StartCoroutine(ShowRoutine(text));
108:     }
109: 
110:     private IEnumerator ShowRoutine(string fullText)
111:     {
112:         isVisible = true;
113:         gameObject.SetActive(true);
114: 
115:         if (canvasGroup != null)
116:         {
117:             canvasGroup.blocksRaycasts = false;
118:         }
119: 
120:         // Pop in animation
121:         float elapsed = 0f;
122:         Vector3 startScale = Vector3.zero;
123:         Vector3 targetScale = Vector3.one;
124: 
125:         if (typewriterSpeed > 0f && dialogueText != null)
126:         {
127:             _typewriterRoutine = StartCoroutine(TypewriterRoutine(fullText));
128:         }
129:         else if (dialogueText != null)
130:         {
131:             dialogueText.text = fullText;
132:         }
133: 
134:         while (elapsed < popDuration)
135:         {
136:             elapsed += Time.deltaTime;
137:             float t = Mathf.Clamp01(elapsed / popDuration);
138:             // Elastic/Overshoot pop curve: 0 -> 1.15 -> 1.0
139:             float scaleProgress = OvershootEase(t);
140:             if (bubbleContainer != null)
141:             {
142:                 bubbleContainer.localScale = Vector3.LerpUnclamped(startScale, targetScale, scaleProgress);
143:             }
144:             if (canvasGroup != null)
145:             {
146:                 canvasGroup.alpha = Mathf.Clamp01(t * 2f);
147:             }
148:             yield return null;
149:         }
150: 
151:         if (bubbleContainer != null) bubbleContainer.localScale = Vector3.one;
152:         if (canvasGroup != null) canvasGroup.alpha = 1f;
153: 
154:         // Auto hide timer
155:         if (autoHideDuration > 0f)
156:         {
157:             _autoHideRoutine = StartCoroutine(AutoHideRoutine(autoHideDuration));
158:         }
159:     }
160: 
161:     private IEnumerator TypewriterRoutine(string fullText)
162:     {
163:         if (dialogueText == null) yield break;
164:         dialogueText.text = "";
165:         float delay = 1f / typewriterSpeed;
166: 
167:         for (int i = 0; i < fullText.Length; i++)
168:         {
169:             dialogueText.text = fullText.Substring(0, i + 1);
170:             yield return new WaitForSeconds(delay);
171:         }
172:     }
173: 
174:     private IEnumerator AutoHideRoutine(float delay)
175:     {
176:         yield return new WaitForSeconds(delay);
177:         Hide();
178:     }
179: 
180:     public void Hide()
181:     {
182:         if (!isVisible && (canvasGroup == null || canvasGroup.alpha <= 0f)) return;
183: 
184:         if (_showRoutine != null) StopCoroutine(_showRoutine);
185:         if (_typewriterRoutine != null) StopCoroutine(_typewriterRoutine);
186:         if (_autoHideRoutine != null) StopCoroutine(_autoHideRoutine);
187: 
188:         _showRoutine = StartCoroutine(HideRoutine());
189:     }
190: 
191:     private IEnumerator HideRoutine()
192:     {
193:         isVisible = false;
194:         float elapsed = 0f;
195:         float hideDur = 0.18f;
196:         Vector3 startScale = bubbleContainer != null ? bubbleContainer.localScale : Vector3.one;
197:         float startAlpha = canvasGroup != null ? canvasGroup.alpha : 1f;
198: 
199:         while (elapsed < hideDur)
200:         {
201:             elapsed += Time.deltaTime;
202:             float t = Mathf.Clamp01(elapsed / hideDur);
203:             if (bubbleContainer != null)
204:             {
205:                 bubbleContainer.localScale = Vector3.Lerp(startScale, Vector3.zero, t);
206:             }
207:             if (canvasGroup != null)
208:             {
209:                 canvasGroup.alpha = Mathf.Lerp(startAlpha, 0f, t);
210:             }
211:             yield return null;
212:         }
213: 
214:         if (bubbleContainer != null) bubbleContainer.localScale = Vector3.zero;
215:         if (canvasGroup != null) canvasGroup.alpha = 0f;
216:         if (dialogueText != null) dialogueText.text = "";
217:     }
218: 
219:     private float OvershootEase(float t)
220:     {
221:         const float c1 = 1.70158f;
222:         const float c3 = c1 + 1f;
223:         return 1f + c3 * Mathf.Pow(t - 1f, 3f) + c1 * Mathf.Pow(t - 1f, 2f);
224:     }
225: }
